let tone;
function setup() {
  createCanvas(480, 280);
  tone = new p5.Oscillator('sine');
  tone.amp(0);
  tone.start();
}
function draw() {
  background(18, 24, 44);
  fill(80, 220, 210);
  const diameter = mouseIsPressed ? 110 : 45;
  circle(constrain(mouseX, 30, width - 30), height / 2, diameter);
}
function mousePressed() {
  userStartAudio();
  tone.freq(map(constrain(mouseX, 0, width), 0, width, 220, 660));
  tone.amp(0.12, 0.02);
}
function mouseReleased() {
  tone.amp(0, 0.1);
}

from tunepad import *

notes = [60, 64, 67, 71]
